// The day's Insights tab, as pure helpers: which state it shows, and the sentences and links in it.

import { ApiError, JobError, UNAUTHORISED, type DayView, type FollowUp, type InsightDayState, type InsightRecord,
  type ProviderFacts } from "./api";
import { hm } from "./format";

/** The privacy sentence for Insights, also shown on Settings > Model. */
export const MODEL_PRIVACY =
  "Insights are generated by the model you choose. With a model on this Mac nothing leaves the machine; " +
  "a cloud provider receives each day's transcript text, never audio.";

export const NO_PROVIDER =
  "Pick a model in Settings › Model to get a summary, follow-ups, people and topics for each day.";
/** The server's words (app.NO_MODEL, stage.NO_SPEECH); the tab compares against them. */
export const NO_MODEL = "No model chosen.";
export const NO_SPEECH = "Nothing to summarise for this day";
export const MODEL_TAB = "#/settings/model";

export type TabState = "no-provider" | "no-speech" | "unusable" | "none" | "generating" | "error" | "done";

/** Whether any conversation of the day has a transcript line. */
export function hasSpeech(view: DayView): boolean {
  return view.conversations.some((c) => c.lines.length > 0);
}

/** What the tab shows. A done insight is shown even when Generate is refused now (a key removed since),
 *  and a running job wins over a refusal, since it is already under way. */
export function tabState(day: InsightDayState, facts: ProviderFacts, view: DayView): TabState {
  if (!facts.provider || day.reason === NO_MODEL) return "no-provider";
  if (!hasSpeech(view) || day.reason === NO_SPEECH) return "no-speech";
  if (day.state === "generating") return "generating";
  if (day.state === "done") return "done";
  if (day.reason) return "unusable";
  return day.state === "error" ? "error" : "none";
}

/** What pressing Generate sends, and where. */
export function generateSentence(facts: ProviderFacts): string {
  return facts.provider === "ollama" ? "Runs on this Mac." : `Sends this day's transcript text to ${facts.display}.`;
}

/** The transcript line a follow-up points at, as a jump within the day; null when it has none. */
export function followUpHref(day: string, fu: FollowUp): string | null {
  return fu.line_id ? `#/day/${day}?${new URLSearchParams({ at: fu.line_id })}` : null;
}

/** "Generated by <model> at 23:05", and a note when the start of the day did not fit. */
export function generatedLine(rec: InsightRecord): string {
  const line = `Generated by ${rec.model} at ${hm(rec.generated_ms)}`;
  return rec.truncated ? `${line} (the earlier part of the day was left out)` : line;
}

/** What a refused or failed Generate or Ask says: the server's own words, or that the app did not answer. */
export function actionError(e: unknown): string {
  if (e instanceof ApiError) return e.status === 401 ? UNAUTHORISED : e.message;
  if (e instanceof JobError) return e.message;
  const why = e instanceof Error ? e.message : String(e);
  return `The app did not answer (${why}). Check that the lavalier app is running.`;
}
